mapper.select:
SELECT  FROM tianquan_oauth.oauth_authentication
WHERE tenant_id = #{tenantId} AND retain_until <= #{now}
  AND id > #{afterId} AND deleted_at IS NULL ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE tianquan_oauth.oauth_authentication
SET status = #{po.status}, retain_until = #{po.retainUntil}, revoked_at = #{po.revokedAt}, reason_code = #{po.reasonCode}, version = #{po.version}, update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND jti_digest = #{po.jtiDigest}
  AND version = #{expectedVersion} AND deleted_at IS NULL

mapper.select:
SELECT  FROM tianquan_oauth.oauth_authentication
WHERE tenant_id = #{tenantId} AND browser_binding_digest = #{binding}
  AND status = 'ACTIVE' AND id > #{afterId} AND deleted_at IS NULL ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE tianquan_oauth.oauth_authentication t
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_time = #{now}, update_user_id = #{actor}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{expectedVersion}
  AND deleted_at IS NULL AND retain_until <= #{now}
  AND expires_at <= #{now}
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_authorization a WHERE a.tenant_id = #{tenantId} AND a.authentication_jti_digest = t.jti_digest AND a.deleted_at IS NULL)
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_interaction i WHERE i.tenant_id = #{tenantId} AND i.authentication_jti_digest = t.jti_digest AND i.deleted_at IS NULL)
